function kk_schema_emit($schema) {
    if (empty($schema)) return;
    echo "\n<script type=\"application/ld+json\">"
        . wp_json_encode($schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
        . "</script>\n";
}

/**
 * Article-family type for a post (#425).
 * Default BlogPosting. NewsArticle only via meta `_kk_schema_type=NewsArticle`
 * or post tag `news-article` (slug). Never blanket-apply NewsArticle.
 */
function kk_schema_post_type($post = null) {
    $post = get_post($post);
    if (!$post) {
        return 'BlogPosting';
    }
    $allowed = array('BlogPosting', 'NewsArticle', 'Article');
    $meta = get_post_meta($post->ID, '_kk_schema_type', true);
    if (is_string($meta) && in_array($meta, $allowed, true)) {
        return $meta;
    }
    if (has_tag('news-article', $post)) {
        return 'NewsArticle';
    }
    return 'BlogPosting';
}

// 1. Person — sitewide
function kk_schema_person() {
    $c = kk_schema_constants();
    $works = array();
    foreach ($c['works_for'] as $org) {
        if (!empty($org['url'])) {
            $works[] = array('@type' => 'Organization', 'name' => $org['name'], 'url' => $org['url']);
        }
    }
    $person = array(
        '@context'      => 'https://schema.org',
        '@type'         => 'Person',
        '@id'           => $c['site_url'] . '/#person',
        'name'          => $c['person_name'],
        'alternateName' => $c['person_alt'],
        'description'   => $c['person_descr'],
        'url'           => $c['site_url'],
        'jobTitle'      => $c['person_job'],
        'worksFor'      => $works,
        'sameAs'        => array_values(array_filter($c['same_as'])),
        'knowsAbout'    => $c['knows_about'],
    );
    if (!empty($c['person_image'])) {
        $person['image'] = $c['person_image'];
    }
    kk_schema_emit($person);
}
add_action('wp_head', 'kk_schema_person', 5);

// 2. WebSite + SearchAction — homepage only
function kk_schema_website() {
    if (!is_front_page() && !is_home()) return;
    $c = kk_schema_constants();
    kk_schema_emit(array(
        '@context'        => 'https://schema.org',
        '@type'           => 'WebSite',
        '@id'             => $c['site_url'] . '/#website',
        'url'             => $c['site_url'],
        'name'            => $c['site_name'],
        'alternateName'   => $c['site_alternate_names'],
        'inLanguage'      => 'en-US',
        'publisher'       => array('@id' => $c['site_url'] . '/#person'),
        'potentialAction' => array(
            '@type'       => 'SearchAction',
            'target'      => array(
                '@type'       => 'EntryPoint',
                'urlTemplate' => $c['site_url'] . '/?s={search_term_string}',
            ),
            'query-input' => 'required name=search_term_string',
        ),
    ));
}
add_action('wp_head', 'kk_schema_website', 6);

// 3. Article — every blog post
function kk_schema_article() {
    if (!is_singular('post')) return;
    $c = kk_schema_constants();
    global $post;

    $image = null;
    if (has_post_thumbnail()) {
        $src = wp_get_attachment_image_src(get_post_thumbnail_id(), 'full');
        if ($src) {
            $image = array(
                '@type'  => 'ImageObject',
                'url'    => $src[0],
                'width'  => $src[1],
                'height' => $src[2],
            );
        }
    }
    $cats = get_the_category();
    $section = ($cats && $cats[0]->name !== 'Misc') ? $cats[0]->name : null;
    $wc = str_word_count(wp_strip_all_tags($post->post_content));

    // #425 rule: BlogPosting default; NewsArticle only when explicitly tagged.
    // Override with post meta `_kk_schema_type` = BlogPosting|NewsArticle|Article.
    $schema_type = kk_schema_post_type($post);

    $schema = array(
        '@context'         => 'https://schema.org',
        '@type'            => $schema_type,
        'headline'         => get_the_title(),
        'description'      => get_the_excerpt(),
        'datePublished'    => get_the_date('c'),
        'dateModified'     => get_the_modified_date('c'),
        'author'           => array('@id' => $c['site_url'] . '/#person'),
        'publisher'        => array('@id' => $c['site_url'] . '/#person'),
        'mainEntityOfPage' => array('@type' => 'WebPage', '@id' => get_permalink()),
        'wordCount'        => $wc,
        'inLanguage'       => 'en-US',
    );
    if ($image)   $schema['image']          = $image;
    if ($section) $schema['articleSection'] = $section;

    kk_schema_emit($schema);
}
add_action('wp_head', 'kk_schema_article', 7);

// 4. BreadcrumbList — non-homepage
function kk_schema_breadcrumb() {
    if (is_front_page()) return;
    $c = kk_schema_constants();
    $items = array(
        array('@type' => 'ListItem', 'position' => 1, 'name' => 'Home', 'item' => $c['site_url']),
    );
    $pos = 2;
    if (is_singular('post')) {
        $items[] = array('@type' => 'ListItem', 'position' => $pos++, 'name' => 'Blog',          'item' => $c['site_url'] . '/blog/');
        $items[] = array('@type' => 'ListItem', 'position' => $pos++, 'name' => get_the_title(), 'item' => get_permalink());
    } elseif (is_page()) {
        $items[] = array('@type' => 'ListItem', 'position' => $pos++, 'name' => get_the_title(), 'item' => get_permalink());
    } elseif (is_category() || is_tag()) {
        $items[] = array('@type' => 'ListItem', 'position' => $pos++, 'name' => single_term_title('', false), 'item' => get_term_link(get_queried_object()));
    }
    kk_schema_emit(array(
        '@context'        => 'https://schema.org',
        '@type'           => 'BreadcrumbList',
        'itemListElement' => $items,
    ));
}
add_action('wp_head', 'kk_schema_breadcrumb', 8);

// 5. Service — pages with a kk_service_audience custom field
function kk_schema_service() {
    if (!is_page()) return;
    $audience = get_post_meta(get_queried_object_id(), 'kk_service_audience', true);
    if (!$audience) return;
    $c = kk_schema_constants();
    kk_schema_emit(array(
        '@context'    => 'https://schema.org',
        '@type'       => 'Service',
        'name'        => wp_strip_all_tags(get_the_title()),
        'description' => wp_strip_all_tags(get_the_excerpt()),
        'provider'    => array('@id' => $c['site_url'] . '/#person'),
        'audience'    => array('@type' => 'Audience', 'audienceType' => $audience),
        'url'         => get_permalink(),
    ));
}
add_action('wp_head', 'kk_schema_service', 9);

/**
 * GSC 404 cleanup — canonicalize legacy tracking query params.
 *
 * Jetpack sharing turns ?share=twitter URLs into off-site 302s. Google indexed
 * those variants separately and reports them in Search Console Coverage.
 *
 * Deploy via Code Snippets on production (Track A). Keep this repo copy in sync.
 * Run early on template_redirect so it wins over Jetpack sharing handlers.
 *
 * When pasting into Code Snippets: strip the opening <?php tag.
 */

declare(strict_types=1);

/**
 * Query keys that should never be indexed as separate URLs.
 */
function kk_gsc404_tracking_query_keys(): array {
    return array('share', 'nb', 'amp');
}

/**
 * Return true when the request carries legacy tracking params we should strip.
 */
function kk_gsc404_has_tracking_query(): bool {
    if (empty($_GET) || !is_array($_GET)) {
        return false;
    }

    foreach (kk_gsc404_tracking_query_keys() as $key) {
        if (array_key_exists($key, $_GET)) {
            return true;
        }
    }

    return false;
}

/**
 * Build the canonical URL for the current request without tracking params.
 */
function kk_gsc404_canonical_target_url(): string {
    $request_uri = isset($_SERVER['REQUEST_URI'])
        ? sanitize_text_field(wp_unslash((string) $_SERVER['REQUEST_URI']))
        : '/';

    $path = (string) wp_parse_url($request_uri, PHP_URL_PATH);
    if ($path === '') {
        $path = '/';
    }

    $path = '/' . ltrim(untrailingslashit($path), '/');
    if ($path !== '/') {
        $path = trailingslashit($path);
    }

    return home_url($path);
}

/**
 * 301 redirect tracking-param variants to the clean canonical URL.
 */
function kk_gsc404_redirect_tracking_query_params(): void {
    if (is_admin() || wp_doing_ajax() || wp_doing_cron()) {
        return;
    }

    if (defined('REST_REQUEST') && REST_REQUEST) {
        return;
    }

    if (!kk_gsc404_has_tracking_query()) {
        return;
    }

    $method = isset($_SERVER['REQUEST_METHOD'])
        ? strtoupper(sanitize_key(wp_unslash((string) $_SERVER['REQUEST_METHOD'])))
        : 'GET';

    if (!in_array($method, array('GET', 'HEAD'), true)) {
        return;
    }

    wp_safe_redirect(kk_gsc404_canonical_target_url(), 301, 'KK GSC404');
    exit;
}
add_action('template_redirect', 'kk_gsc404_redirect_tracking_query_params', 0);

/**
 * KK Asset Diet — kriskrug.co
 *
 * Cuts unused plugin CSS/JS flagged by Google PageSpeed ("Reduce unused CSS",
 * "Reduce unused JavaScript"). Deployed via the Code Snippets plugin on
 * production as the "KK Asset Diet" snippet (front-end scope). This file is the
 * source of truth — keep it in sync if either side is edited.
 *
 * Verified live 2026-06-28: every page was loading Jetpack Instant Search
 * (jp-search.js, served unminified), Jetpack Carousel + Swiper, Jetpack Sharing
 * (sharedaddy), Popup Maker (one site-wide auto-open popup #3884), and jQuery
 * Migrate. The kk-aurora theme itself is clean — its CSS/JS is concatenated and
 * minified by Jetpack Boost, so the reducible weight is all plugin JavaScript.
 *
 * Reversible by design: deleting this snippet (or Code Snippets safe-mode)
 * restores instant search, carousel, sharing, the popup, and jQuery Migrate.
 *
 * When pasting into Code Snippets: strip the opening <?php tag (Code Snippets
 * wraps the snippet automatically).
 */

/**
 * 1. Disable Jetpack modules KK doesn't use: Instant Search, Carousel, Sharing.
 *    Search reverts to the lightweight core search form.
 */
add_filter('jetpack_active_modules', function (array $modules): array {
    return array_values(array_diff($modules, ['search', 'carousel', 'sharedaddy']));
});

/**
 * 2. Drop jQuery Migrate on the front end. It is a legacy-API shim with no
 *    modern consumer once the plugins above stop loading.
 */
add_action('wp_default_scripts', function ($scripts): void {
    if (is_admin()) {
        return;
    }
    $jquery = $scripts->registered['jquery'] ?? null;
    if ($jquery && !empty($jquery->deps)) {
        $jquery->deps = array_diff($jquery->deps, ['jquery-migrate']);
    }
});

/**
 * 3. Retire the site-wide auto-open Popup Maker popup (#3884) and its assets.
 *    pum_popup_is_loadable => false stops Popup Maker rendering AND enqueuing
 *    any popup. The dequeue is belt-and-suspenders against PM's combined asset
 *    cache, whose real handle is "popup-maker-site" (not "pum-site-*").
 */
add_filter('pum_popup_is_loadable', '__return_false');
add_action('wp_enqueue_scripts', function (): void {
    wp_dequeue_style('popup-maker-site');
    wp_dequeue_script('popup-maker-site');
}, 100);

/**
 * 4. Drop jQuery on the front end. The audit found no consumer: kk-aurora theme
 *    JS is vanilla, no enqueued script declares a jquery dep, and there are zero
 *    inline jQuery()/$() calls across every page type. Dequeue (not deregister)
 *    is self-protecting: if some script genuinely depends on jquery, WordPress
 *    re-adds it at print time, so this only removes jquery where it is unused.
 */
add_action('wp_enqueue_scripts', function (): void {
    if (is_admin()) {
        return;
    }
    wp_dequeue_script('jquery');
    wp_dequeue_script('jquery-core');
}, 100);

/**
 * Google News-style sitemap — kriskrug.co (#425)
 *
 * DRAFT for Code Snippets. Do not paste/activate without KK approval.
 * Emits only posts classified as NewsArticle (see kk_schema_post_type in
 * schema-snippets-deployed.php) from the last 48 hours at /news-sitemap.xml.
 *
 * When pasting into Code Snippets: strip the opening <?php tag.
 */

if (!defined('ABSPATH')) {
    exit;
}

add_action('init', function () {
    add_rewrite_rule('^news-sitemap\.xml$', 'index.php?kk_news_sitemap=1', 'top');
    add_rewrite_tag('%kk_news_sitemap%', '1');
    // One-shot flush after first activate (avoids a manual Permalinks visit).
    if (get_option('kk_news_sitemap_flushed') !== '1') {
        flush_rewrite_rules(false);
        update_option('kk_news_sitemap_flushed', '1', true);
    }
});

add_filter('query_vars', function ($vars) {
    $vars[] = 'kk_news_sitemap';
    return $vars;
});

add_action('template_redirect', function () {
    if (!get_query_var('kk_news_sitemap')) {
        return;
    }

    $posts = get_posts(array(
        'post_type'           => 'post',
        'post_status'         => 'publish',
        'posts_per_page'      => 100,
        'ignore_sticky_posts' => true,
        'date_query'          => array(
            array(
                'after'     => '48 hours ago',
                'inclusive' => true,
            ),
        ),
        'orderby'             => 'date',
        'order'               => 'DESC',
    ));

    header('Content-Type: application/xml; charset=UTF-8');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n";
    echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"'
        . ' xmlns:news="http://www.google.com/schemas/sitemap-news/0.9">' . "\n";

    foreach ($posts as $post) {
        $type = function_exists('kk_schema_post_type')
            ? kk_schema_post_type($post)
            : 'BlogPosting';
        if ($type !== 'NewsArticle') {
            continue;
        }
        $loc = esc_url(get_permalink($post));
        $title = esc_html(get_the_title($post));
        $pub = get_the_date('c', $post);
        echo "  <url>\n";
        echo "    <loc>{$loc}</loc>\n";
        echo "    <news:news>\n";
        echo "      <news:publication>\n";
        echo "        <news:name>Kris Krug</news:name>\n";
        echo "        <news:language>en</news:language>\n";
        echo "      </news:publication>\n";
        echo "      <news:publication_date>{$pub}</news:publication_date>\n";
        echo "      <news:title>{$title}</news:title>\n";
        echo "    </news:news>\n";
        echo "  </url>\n";
    }

    echo '</urlset>';
    exit;
});

/**
 * After first activate: flush rewrite rules once (Settings → Permalinks → Save)
 * or run `flush_rewrite_rules()` from a one-shot admin action.
 */
